def span(g, vert=True):
    o=[r[:] for r in g]; h=len(o); w=len(o[0]); ch=True
    while ch:
        ch=False; o2=[r[:] for r in o]
        for i,row in enumerate(o2):
            bycol={}
            for j,v in enumerate(row):
                if v: bycol.setdefault(v,[]).append(j)
            for c,pos in bycol.items():
                a,b=min(pos),max(pos)
                if len(pos)>=2 and all(row[j]==0 for j in range(a+1,b)):
